   201  static const char *VoiceFromStack(SSML_STACK *ssml_stack, int n_ssml_stack, espeak_VOICE *base_voice, char base_voice_variant_name[40])
   202  {
   203          // Use the voice properties from the SSML stack to choose a voice, and switch
   204          // to that voice if it's not the current voice
   205
   206          int ix;
   207          const char *p;
   208          SSML_STACK *sp;
   209          const char *v_id;
   210          int voice_name_specified;
   211          int voice_found;
   212          espeak_VOICE voice_select;
   213          static char voice_name[40];
   214          char language[40];
   215          char buf[80];
   216
   217          strcpy(voice_name, ssml_stack[0].voice_name);
   218          strcpy(language, ssml_stack[0].language);
   219          voice_select.age = ssml_stack[0].voice_age;
   220          voice_select.gender = ssml_stack[0].voice_gender;
   221          voice_select.variant = ssml_stack[0].voice_variant_number;
   222          voice_select.identifier = NULL;
   223
   224          for (ix = 0; ix < n_ssml_stack; ix++) {
   225                  sp = &ssml_stack[ix];
   226                  voice_name_specified = 0;
   227
   228                  if ((sp->voice_name[0] != 0) && (SelectVoiceByName(NULL, sp->voice_name) != NULL)) {
   229                          voice_name_specified = 1;
   230                          strcpy(voice_name, sp->voice_name);
   231                          language[0] = 0;
   232                          voice_select.gender = ENGENDER_UNKNOWN;
   233                          voice_select.age = 0;
   234                          voice_select.variant = 0;
   235                  }
   236                  if (sp->language[0] != 0) {
   237                          strcpy(language, sp->language);
   238
   239                          // is this language provided by the base voice?
   240                          p = base_voice->languages;
   241                          while (*p++ != 0) {
   242                                  if (strcmp(p, language) == 0) {
   243                                          // yes, change the language to the main language of the base voice
   244                                          strcpy(language, &base_voice->languages[1]);
   245                                          break;
   246                                  }
   247                                  p += (strlen(p) + 1);
   248                          }
   249
   250                          if (voice_name_specified == 0)
   251                                  voice_name[0] = 0; // forget a previous voice name if a language is specified
   252                  }
   253                  if (sp->voice_gender != ENGENDER_UNKNOWN)
   254                          voice_select.gender = sp->voice_gender;
   255
   256                  if (sp->voice_age != 0)
   257                          voice_select.age = sp->voice_age;
   258                  if (sp->voice_variant_number != 0)
   259                          voice_select.variant = sp->voice_variant_number;
   260          }
   261
   262          voice_select.name = voice_name;
   263          voice_select.languages = language;
   264          v_id = SelectVoice(&voice_select, &voice_found);
   265          if (v_id == NULL)
   266                  return "default";
   267
   268          if ((strchr(v_id, '+') == NULL) && ((voice_select.gender == ENGENDER_UNKNOWN) || (voice_select.gender == base_voice->gender)) && (base_voice_variant_name[0] != 0)) {
   269                  // a voice variant has not been selected, use the original voice variant
   270                  sprintf(buf, "%s+%s", v_id, base_voice_variant_name);
   271                  strncpy0(voice_name, buf, sizeof(voice_name));
   272                  return voice_name;
   273          }
   274          return v_id;
   275  }
